// chapter, title, symptom, steps, prevention, escalation, primary source (optional)
const helpArticles=[
[0,'Не могу войти в аккаунт','Пароль не подходит, код не приходит или потерян доступ.', ['Проверь ник и доступ к привязанной почте или телефону. Используй восстановление на экране входа Instagram.','Если подозреваешь взлом, выбирай официальный сценарий восстановления, а не случайные ссылки в сообщениях.','Сохрани сведения об ошибке. Не передавай пароль и коды «специалистам по разблокировке».'], 'До старта проверь контакты восстановления и настрой двухфакторную защиту. Резервные коды храни отдельно от телефона.', 'Продолжай через официальный центр поддержки аккаунта. Курс не может восстановить доступ за тебя.','meta'],
[0,'В статусе аккаунта предупреждение','Уведомление об удалении, ограничении функции или рекомендаций.', ['Открой само уведомление и прочитай причину, затронутые материалы и доступные действия.','Если доступен пересмотр и ты не согласен, отправь запрос с объяснением. Не удаляй всё подряд.','Зафиксируй дату и состояние. До решения не повторяй действие, которое указано в предупреждении.'], 'Проверяй статус до начала работы и после новых предупреждений. Допуск к рекомендациям не обещает конкретное число просмотров.', 'Используй указанный в приложении процесс пересмотра. Срок решения заранее неизвестен.','recommendations'],
[0,'Настройки выглядят иначе','В телефоне нет переключателя со скриншота курса.', ['Сверь название и назначение функции, а не её положение на экране.','Проверь обновление приложения и выбранный аккаунт. Не меняй тип аккаунта наугад ради одной кнопки.','В миссии отметь «Пункт недоступен» или «Нужно разобраться» и продолжай остальные шаги.'], 'Скриншоты показывают мою конфигурацию. Интерфейс зависит от версии, устройства и доступности функции.', 'Поищи название функции в справке внутри приложения; сохрани свой скриншот без личных данных.'],
[0,'Старые публикации исчезли','После очистки профиля не вижу прежние материалы.', ['Уточни, была ли команда «Архивировать» или «Удалить».','Проверь архив и доступные разделы восстановления в самом приложении.','Возвращай нужные публикации через доступную команду. Не обещаем восстановление удалённого материала вне условий платформы.'], 'Перед подтверждением читай название действия. Для схемы курса используется архивирование, не удаление.', 'Если материал не найден, используй поддержку Instagram и укажи дату и тип действия.'],
[1,'Лента не показывает мою нишу','В рекомендациях случайные видео вместо подходящих идей.', ['Начни с поиска по теме и конкретным авторам. Сохрани отдельную подборку аккаунтов.','Взаимодействуй с действительно интересными публикациями и отмечай нерелевантные доступными средствами.','Не жди, пока вся лента изменится: собирай банк ссылок вручную.'], 'В моём методе это важный этап настройки ленты: просмотры, лайки и сохранения дают системе сигналы о твоих интересах. Подтверждённый эффект относится к рекомендациям, которые видишь ты; автоматический выбор аудитории твоих роликов из этого не следует.', 'Если не находится материал, расширь тему и язык поиска; оцени отдельные аккаунты.','feed'],
[1,'Просмотры скрыты или показатели непонятны','Нельзя применить обычный порог отбора референса.', ['Запиши доступные показатели и дату проверки. Не заменяй просмотры охватом незаметно для себя.','Для свежего ролика мой запасной ориентир - от 100 лайков и 10 репостов. Для старого - 5–7 тысяч лайков и от 1 тысячи репостов.','Если не видны и эти данные, пометь идею как непроверенную. Не выдумывай цифры.'], 'Свежий референс: до 10 дней, просмотры от 1,8 × числа подписчиков. Пороги - фильтр метода, не прогноз.', 'Выбери другой пример с доступными данными или тестируй тему как собственную гипотезу.'],
[1,'Чужая идея не подходит моему блогу','Есть сильный ролик, но не получается связать его с собой.', ['Выпиши тему и интерес зрителя одним предложением.','Найди собственный опыт, наблюдение или проверенный пример, который раскрывает этот интерес.','Если связи нет - отложи референс. Не меняй нишу ради одной удачной публикации.'], 'Добавляй в банк идей поле «моя мысль». Список ссылок без своего содержания не равен контент-плану.', 'Вернись к миссии о темах и составь три пересечения широкой темы с твоим блогом.'],
[2,'ИИ повторяется и пишет без конкретики','Пафосные фразы, повторения, длинные вступления.', ['Передай тему, аудиторию и 2–3 примера своей естественной речи.','Попроси убрать вступление, раскрыть одну мысль и заменить общие фразы конкретными примерами.','Сравни варианты вслух и отредактируй своими словами.'], 'Сохраняй базовый промпт и отдельную карточку голоса. Новый чат начинай с контекста.', 'Раздели задачу: сначала структура, затем один пункт, затем финальная редактура.'],
[2,'ИИ придумал факты или мой опыт','В тексте появились доходы, цитаты, «мой знакомый» или достижения, которых не было.', ['Выдели все проверяемые утверждения.','Подтверди их первоисточниками либо убери. Условный пример так и называй условным.','Запрети редактору добавлять числа и личные истории без твоих данных.'], 'Сохраняй ссылки рядом с фактами. Большие просмотры исходного ролика не подтверждают достоверность его текста.', 'Если проверить утверждение нельзя, перепиши мысль без него. Для медицинских и иных ответственных тем нужна отдельная компетентная проверка.'],
[2,'Хук обещает больше, чем описание','Зритель открывает текст, но не получает ответа.', ['Сформулируй обещание хука отдельно.','Найди в описании конкретный ответ. Если написано «три причины», проверь наличие всех трёх.','Сократи или уточни хук, если материал не раскрывает его честно.'], 'Проверяй пару «хук + описание» перед монтажом. Используй предполётную проверку в приложении.', 'Начни с главного вывода описания и напиши хук заново под него.'],
[3,'Не вижу видео при импорте','Edits показывает не всю галерею или не открывает файл.', ['Открой исходник в приложении «Фото» и убедись, что он воспроизводится полностью.','Проверь доступ Edits к нужным фото и видео в настройках телефона. При ограниченном доступе добавь конкретный файл.','Если исходник хранится в облаке, дождись его загрузки на устройство и попробуй импорт снова.'], 'Перед съёмочной сессией проверь разрешения и наличие оригиналов на телефоне.', 'Попробуй короткое новое видео. Если импортируется только оно, проблема, вероятно, связана с исходным файлом; сохрани оригинал.','photos'],
[3,'Видео размыто, темно или дёргается','Подложка выглядит хуже ожидаемого ещё до монтажа.', ['Протри объектив, проверь освещение и фокус на главном объекте.','Сними короткий тест без цифрового приближения и резких движений.','Посмотри исходник в галерее: если дефект уже там, пересними, а не пытайся исправить экспортом.'], 'Снимай 12–15 секунд с запасом, чтобы выбрать спокойные 5–6 секунд.', 'Упрости сцену: больше света, неподвижный телефон, одно действие.'],
[3,'Сток красивый, но непонятно, можно ли использовать','В кадре люди, логотипы или чужая музыка.', ['Открой страницу материала и условия ресурса.','Проверь ограничения и наличие в кадре брендов или узнаваемых людей; не создавай ложное впечатление их поддержки продукта.','Сохрани ссылку и условия. Музыку оцени отдельно от видеоряда.'], 'Бесплатный файл не означает отсутствие всех ограничений. Для важных кадров удобнее собственная съёмка.', 'При неясных условиях выбери другой материал или получи разрешение.','stock'],
[3,'Закончились свежие подложки','Одни и те же кадры начинают повторяться.', ['Проверь архив длинных исходников и выбери другие фрагменты.','Подготовь небольшую съёмку: три действия в двух местах.','Связывай кадры с текстом. Кроп и изменение скорости не гарантируют оригинальность для платформы.'], 'Разделяй исходники, готовые фрагменты и опубликованные версии. Записывай, где использован кадр.', 'Снизь сложность производства и пополни банк, сохраняя самостоятельность каждого ролика.'],
[4,'Edits зависает или закрывается','Проект не открывается, экран замер или приложение вылетает.', ['Если возможно, сохрани проект и экспортируй важные версии.','Закрой зависшее приложение, открой снова; при повторении перезапусти телефон и проверь обновления.','Проверь свободное место и нагрев устройства. Попробуй простой проект из одного короткого клипа.'], 'Храни исходники и готовые экспорты отдельно. Не начинай с переустановки: локальные данные приложения могут потеряться.', 'Если сбой остаётся, отправь разработчику модель телефона, версии ОС и Edits, шаги и снимок ошибки.','apple'],
[4,'Экспорт останавливается или даёт чёрный кадр','Ролик не сохраняется, зависает на проценте или повреждён.', ['Оставь исходный проект. Если доступно, создай копию для проверки.','Проверь место на устройстве. Попробуй экспорт короткого фрагмента в более низком разрешении.','В копии по одному отключай недавно добавленные эффекты и слои; сравни результат.','Если простой проект экспортируется, заново добавь проблемный исходник или пересобери повреждённый участок.'], 'Проверяй экспорт до запуска большой партии. Параметры и наличие команд зависят от версии Edits.', 'Это диагностическая последовательность, не подтверждённое универсальное исправление Edits. При повторении передай детали в поддержку.','edits'],
[4,'Хук обрезан или пропадает раньше конца','Надпись перекрывают кнопки либо слой слишком короткий.', ['Растяни текстовый слой от начала до конца ролика.','Проверь первый, средний и последний кадр.','Уменьши число слов и отступи от краёв, нижнего описания и правых кнопок. Посмотри предпросмотр публикации.'], 'Сначала проверяй читаемость в размере телефона. Схема в предполётной проверке - ориентир, не точная сетка Instagram.', 'Если читается плохо, сократи хук, а не только шрифт.'],
[4,'После экспорта изменились цвета или звук','Видео бледное, пересвеченное, без музыки или с рассинхроном.', ['Сравни исходник, предпросмотр Edits и файл в галерее. Найди этап, на котором появился дефект.','Для проверки цвета попробуй обычный SDR-вариант, если настройка доступна.','Проверь громкость слоёв, выключение звука и скорость клипа. Экспортируй короткий тест.'], 'Смотри файл со звуком до публикации. Смена скорости после монтажа может потребовать повторной сверки.', 'Если готовый файл нормальный, а публикация нет, переходи к карточке про звук после загрузки.'],
[4,'Ролик не загружается или выходит дважды','Загрузка зависла, непонятно, была ли публикация завершена.', ['Сохрани файл и описание вне Instagram.','Проверь соединение и наличие ролика в профиле до повторной отправки.','Если файл воспроизводится локально, попробуй загрузку готового экспорта через Instagram вместо прямого перехода из Edits.','При сообщении об ограничении действий останови повторы и прочитай сообщение.'], 'После каждой отправки сверяй результат. Календарь заполняй только фактически опубликованными роликами.', 'Если проблема повторяется, запиши время, размер файла, устройство, сеть и точный текст ошибки; отправь технический отчёт через доступную помощь приложения.','edits'],
[4,'Описание обрезалось или не вставляется','После публикации пропал конец или поле не принимает текст.', ['Сохрани полный вариант в заметках.','Сравни реально сохранённый текст с исходником; открой редактирование и вставь его снова.','Если не сохраняется, попробуй более короткий обычный текст без сложного форматирования.','Проверь повторно после сохранения. Причина может быть в длине, содержимом, соединении или сбое.'], 'Не используй поле Instagram как единственное место хранения. Не утверждай, что любое невставляющееся описание обязательно превышает лимит.', 'Если короткий текст тоже не сохраняется, проверь статус и повтори диагностику загрузки; затем отправь отчёт.'],
[4,'Музыка пропала или недоступна','Трек заглушён, исчез из библиотеки или не доступен этому аккаунту.', ['Проверь звук в экспортированном файле и сообщение самой платформы.','Уточни условия использования выбранной записи и доступность её для твоего типа публикации.','Выбери собственный звук или трек с подходящими разрешениями; при наличии используй замену аудио в приложении.'], 'Название «оригинальное аудио» не выдаёт разрешение на чужую музыку. Сохраняй монтаж без зависимости от одного трека.', 'Не перезаливай спорную запись бесконечно. Если есть уведомление о правах, действуй по нему и по доступным процедурам.'],
[5,'Нет пробного режима','Переключатель Trial не появляется или исчез.', ['Проверь правильный аккаунт и обновление приложения.','Открой обычный экран создания ролика и найди доступные параметры аудитории.','Если функции нет, выбери обычный режим в календаре. Не покупай подписчиков ради предполагаемого порога.'], 'Нет подтверждённой гарантии, что функция появится именно при 200 подписчиках. Не привязывай весь процесс к её наличию.', 'Сверь доступность с актуальной справкой в приложении. Продолжай работу в доступном режиме.','trial'],
[5,'Пробный ролик увидели подписчики','Хотел протестировать только на новой аудитории.', ['Проверь, не выбран ли общий показ или автоматический перевод.','Учти, что подписчик может встретить пробный ролик через пересылку или другие поверхности.','Если материал должен оставаться конфиденциальным, не используй пробный режим как закрытый доступ.'], 'Meta описывает показы неподписчикам в первую очередь, а не абсолютную невидимость для знакомых.', 'Для контроля общей публикации проверяй переключатели конкретного ролика.','trial'],
[5,'Не удаётся выпустить больше четырёх пробных','Приложение перестало принимать следующую пробную публикацию.', ['Сохрани точное сообщение и убедись, что предыдущие ролики действительно вышли.','Проверь статус аккаунта. Если указано ограничение действий, не увеличивай нагрузку в обход него.','Если недоступна только функция и предупреждений нет, оставь готовые ролики в запасе и используй доступный обычный режим по своему плану.'], 'Четыре ролика - моё наблюдение, не универсальный лимит Instagram. Запас контента снижает давление при сбое.', 'При устойчивой технической ошибке отправь отчёт из приложения. Не обещаем «разблокировку» сменой количества роликов.'],
[5,'Пропустил день и боюсь начинать заново','Сбился график, нет запаса или слишком большая нагрузка.', ['Зафиксируй фактический пропуск, не ставь ложную отметку.','Подготовь небольшую партию и вернись к посильному объёму.','После длительного перерыва можно начать новый цикл с постепенным разгоном; старые записи сохраняются.'], 'Один пропуск не доказывает поломку охватов. Разделяй дни съёмки, текстов и публикации.', 'Если темп постоянно не выдерживается, пересмотри объём и время подготовки, а не наказывай себя удвоенной нормой.'],
[6,'Около 200 просмотров и нет новой аудитории','Результат стоит на месте, кажется, что аккаунт заблокирован.', ['Проверь статус и фактическую видимость публикаций.','Сравни несколько роликов одинакового возраста и доступные данные о неподписчиках.','Проверь хук, описание и тему. Изменяй один основной элемент за серию попыток.','Если технических предупреждений нет, продолжай ограниченный эксперимент и записывай результаты.'], 'Низкие просмотры не являются диагнозом «теневого бана». Разрешённый контент тоже может не подходить для рекомендаций.', 'Если есть уведомление - действуй по нему. Если нет - переходи к новой гипотезе, не удаляя историю наугад.','recommendations'],
[6,'Просмотры есть, а подписок нет','Ролик привлёк людей, но они не остаются.', ['Сравни тему ролика с обещанием профиля и следующими публикациями.','Проверь доступные переходы в профиль и подписки от ролика, не смешивая метрики.','Уточни оформление и приглашение остаться; подготовь продолжение темы.'], 'Большой охват сам по себе не означает целевую аудиторию или клиентов.', 'Сделай серию на одну близкую блогу тему и сравни качество реакции, а не только максимум просмотров.'],
[6,'Статистика разных экранов не совпадает','В Edits, Instagram и карточке ролика разные числа.', ['Проверь, сравниваешь ли один ролик, один период и одну метрику.','Отличай просмотры от уникально охваченных аккаунтов и подписок.','Зафиксируй источник и время снимка. Вернись позже, если публикация свежая.'], 'Используй одинаковый возраст роликов при сравнении. Не вычитай разные метрики друг из друга.', 'Если расхождение сохраняется для одной и той же метрики, приложи оба скриншота и время к техническому отчёту.'],
[7,'Пропал прогресс курса','На другом телефоне или в другом браузере пустые ответы.', ['Открой тот браузер и адрес приложения, где проходил курс.','В «Рюкзаке» скачай резервную копию JSON, если старые данные ещё доступны.','На новом устройстве выбери восстановление копии и проверь число миссий перед заменой.'], 'Сейчас данные хранятся на устройстве. Очистка данных сайта, приватный режим и смена браузера могут сделать их недоступными.', 'Если локальные данные удалены и копии нет, приложение не сможет восстановить их с сервера.'],
[7,'Не получается закрыть окно или выбрать дату','На телефоне поле вылезает за край, мешает клавиатура.', ['Закрой клавиатуру, затем нажми крестик окна.','В обновлённой версии поле даты ограничено шириной окна; при необходимости прокрути само окно.','Если видишь старый интерфейс, обнови страницу, сохранив важный текст перед обновлением.'], 'Используй актуальную версию браузера. Масштаб текста можно увеличивать: основные элементы должны оставаться доступными.', 'Запиши модель телефона, браузер, масштаб и шаги воспроизведения. Кнопка ниже поможет составить отчёт.'],
[7,'Копирование или скачивание не сработало','Браузер не дал доступ к буферу или файл не найден.', ['При отказе копирования выдели видимый текст вручную.','Проверь раздел загрузок браузера и приложение «Файлы».','Открой курс в обычном браузере, если встроенное окно ограничивает скачивание.'], 'Карточка TXT - текстовая копия, JSON - перенос прогресса. Для восстановления нужен именно JSON Кадра.', 'Не загружай неизвестные файлы вместо резервной копии. Если файл не читается, сохрани текущие данные перед повторной попыткой.']
].map((x,i)=>({id:i,stage:x[0],title:x[1],symptom:x[2],steps:x[3],prevent:x[4],escalate:x[5],source:x[6]}));
const helpStages=[...chapters.map(c=>c.title),'Приложение Кадр'];
let helpStage='all',helpQuery='',helpSavedOnly=false;
function helpMatches(){const q=helpQuery.toLocaleLowerCase('ru').replace(/ё/g,'е').trim();return helpArticles.filter(a=>(helpStage==='all'||a.stage===Number(helpStage))&&(!helpSavedOnly||state.fields['helpSaved_'+a.id])&&(!q||[a.title,a.symptom,...a.steps,a.prevent].join(' ').toLocaleLowerCase('ru').replace(/ё/g,'е').includes(q)))}
function helpCenter(){app.innerHTML=`<section class="help-hero"><img src="assets/stickers/idea.svg" alt=""><div><span class="tiny">МАСТЕРСКАЯ РЕШЕНИЙ</span><h1>Если что-то пошло не так.</h1><p>Найди симптом, пройди проверку и вернись к своему шагу.</p></div></section><div class="help-tools"><label class="field">Что случилось?<input id="helpSearch" type="search" value="${esc(helpQuery)}" placeholder="Например: экспорт, описание, пробный"></label><label class="field">Этап<select id="helpStage"><option value="all">Все этапы</option>${helpStages.map((s,i)=>`<option value="${i}" ${String(i)===helpStage?'selected':''}>${s}</option>`).join('')}</select></label><button class="secondary" id="helpSaved" aria-pressed="${helpSavedOnly}">${helpSavedOnly?'Показать все':'Мои закладки'}</button></div><div class="actions"><button class="primary" data-view="preflight">Проверить ролик перед выходом <svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 12h16m-6-6 6 6-6 6"/></svg></button><button class="secondary" id="supportReport">Составить отчёт об ошибке</button></div><p class="note">Проверено 28 октября 2026. Пошаговые проверки - практические рекомендации, не гарантия исправления. Подтверждённые возможности платформ отмечены ссылками; названия меню могут отличаться.</p><p id="helpCount" role="status"></p><div id="helpResults"></div>`;helpResults()}
function helpResults(){const list=helpMatches();document.querySelector('#helpCount').textContent=`Найдено решений: ${list.length}`;document.querySelector('#helpResults').innerHTML=list.length?list.map(a=>`<details class="help-article"><summary><span class="tiny">${helpStages[a.stage]}</span><strong>${a.title}</strong></summary><div class="help-article-body"><p class="help-symptom">${a.symptom}</p><h3>Что сделать сейчас</h3><ol>${a.steps.map(s=>`<li>${s}</li>`).join('')}</ol><h3>Как избежать заранее</h3><p>${a.prevent}</p><h3>Если не помогло</h3><p>${a.escalate}</p>${a.source?`<a href="${helpSources[a.source][1]}" target="_blank" rel="noopener">${helpSources[a.source][0]} <svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M6 18 18 6M6 6h12v12"/></svg></a>`:'<small class="note">Мой практический разбор.</small>'}<div class="actions"><button class="secondary" data-save-help="${a.id}" aria-pressed="${!!state.fields['helpSaved_'+a.id]}">${state.fields['helpSaved_'+a.id]?'Убрать закладку':'Сохранить решение'}</button>${a.stage<7?`<button class="quiet" data-view="chapter/${a.stage+1}">К главе <svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 12h16m-6-6 6 6-6 6"/></svg></button>`:''}</div></div></details>`).join(''):'<div class="content-block"><h3>Точного совпадения нет</h3><p>Попробуй более короткое слово или другой этап.</p><button class="secondary" id="clearHelp">Сбросить поиск</button></div>'}
function lessonExtras(i){const b=document.querySelector('.lesson-body');if(!b)return;b.insertAdjacentHTML('afterbegin',`<div class="lesson-tools"><button class="secondary" data-bookmark="${i}" aria-pressed="${!!state.fields['bookmark_'+i]}">${state.fields['bookmark_'+i]?'В закладках':'Сохранить миссию'}</button><button class="quiet" data-help-stage="${Math.floor(i/6)}">Трудности на этом этапе <svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 12h16m-6-6 6 6-6 6"/></svg></button></div>`)}
const preflightItems=['Хук понятен и виден от начала до конца','Описание выполняет обещание хука; факты проверены','Кадр и звук можно использовать','Текст не перекрыт интерфейсом в предпросмотре','Готовый файл просмотрен со звуком','Выбран нужный аккаунт и режим публикации','Исходник и описание сохранены отдельно'];
function preflight(){app.innerHTML=`<section class="screen-heading"><span class="tiny">ПРЕДПОЛЁТНАЯ ПРОВЕРКА</span><h1>Перед тем как нажать «Опубликовать».</h1><p>Собери текст и проверь семь пунктов. Отметки сохраняются до следующего ролика.</p></section><div class="preflight-layout"><section class="content-block">${area('flightHook','Хук на видео','Одна понятная мысль')}${area('flightCaption','Описание ролика','Обещание хука → объяснение → вывод')}<p id="flightCount" class="note"></p><div class="actions"><button class="secondary" id="copyFlight">Скопировать комплект</button><button class="quiet" id="resetFlight">Снять отметки для следующего ролика</button></div></section><section class="content-block"><div class="phone-mock"><span>ПРИМЕР РАЗМЕЩЕНИЯ</span><div id="flightPreview"></div><small>Оставь место под описание и кнопки интерфейса</small></div><p class="note">Это схема для оценки читаемости. Финальную проверку делай в предпросмотре самой платформы.</p></section></div><section class="content-block"><h2>Проверка готовности</h2>${preflightItems.map((x,i)=>check('flightCheck_'+i,x)).join('')}<p id="flightStatus" role="status"></p><button class="primary" data-view="calendar">Перейти к календарю <svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 12h16m-6-6 6 6-6 6"/></svg></button></section>`;updatePreflight()}
function updatePreflight(){const h=String(state.fields.flightHook||''),c=String(state.fields.flightCaption||'');document.querySelector('#flightPreview').textContent=h||'Здесь появится твой хук';document.querySelector('#flightCount').textContent=`Хук: ${Array.from(h).length} символов · описание: ${Array.from(c).length}. Это счётчик, а не проверка лимита Instagram.`;const n=preflightItems.filter((_,i)=>state.fields['flightCheck_'+i]).length;document.querySelector('#flightStatus').textContent=n===7?'7 / 7. Проверка завершена - можно перейти к публикации.':`${n} / 7. Осталось проверить: ${7-n}.`}
function reportText(){return `ОШИБКА\nПриложение: ${state.fields.reportApp||'—'}\nУстройство и версия ОС: ${state.fields.reportDevice||'—'}\nВерсия приложения: ${state.fields.reportVersion||'—'}\nЧто сделал и что произошло: ${state.fields.reportSteps||'—'}\nОжидаемый результат: ${state.fields.reportExpected||'—'}\nВремя и часовой пояс: ${state.fields.reportTime||'—'}\nЧто уже проверил: ${state.fields.reportTried||'—'}\n\nПриложите скриншот без паролей, кодов и личных переписок.`}
function showReport(){document.querySelector('#rewardContent').innerHTML=`<button id="closeReward" class="modal-close" aria-label="Закрыть"><svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M6 6l12 12M18 6 6 18"/></svg></button><h2>Отчёт, который понятен поддержке</h2><p>Заполни и скопируй. Ничего не отправляется автоматически.</p>${select('reportApp','Где ошибка?',['Кадр','Instagram','Edits'])}${field('reportDevice','Телефон и версия ОС')}${field('reportVersion','Версия приложения')}${area('reportSteps','Шаги и точная ошибка')}${field('reportExpected','Что должно было произойти')}${field('reportTime','Когда, включая часовой пояс')}${area('reportTried','Что уже пробовал')}<button class="primary" id="copyReport">Скопировать отчёт</button><p class="note">Для Instagram и Edits используй доступную помощь внутри приложения. Адрес поддержки Кадра будет добавлен перед запуском продаж.</p>`;openDialog('reward')}
document.addEventListener('input',e=>{if(e.target.id==='helpSearch'){helpQuery=e.target.value;helpResults()}if(e.target.dataset.field?.startsWith('flight'))updatePreflight()});
document.addEventListener('change',e=>{if(e.target.id==='helpStage'){helpStage=e.target.value;helpResults()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.helpStage!==undefined){helpStage=b.dataset.helpStage;helpQuery='';helpSavedOnly=false;render('help')}if(b.id==='helpSaved'){helpSavedOnly=!helpSavedOnly;helpCenter()}if(b.id==='clearHelp'){helpQuery='';helpStage='all';helpSavedOnly=false;helpCenter()}if(b.dataset.saveHelp!==undefined){const key='helpSaved_'+b.dataset.saveHelp;state.fields[key]=!state.fields[key];persist();b.textContent=state.fields[key]?'Убрать закладку':'Сохранить решение';b.setAttribute('aria-pressed',String(state.fields[key]));if(helpSavedOnly)helpResults()}if(b.dataset.bookmark!==undefined){const key='bookmark_'+b.dataset.bookmark;state.fields[key]=!state.fields[key];persist();b.textContent=state.fields[key]?'В закладках':'Сохранить миссию';b.setAttribute('aria-pressed',String(state.fields[key]))}if(b.id==='copyFlight')copy(`ХУК\n${state.fields.flightHook||''}\n\nОПИСАНИЕ\n${state.fields.flightCaption||''}`);if(b.id==='resetFlight'){preflightItems.forEach((_,i)=>state.fields['flightCheck_'+i]=false);persist();preflight();toast('Отметки сняты. Тексты оставлены для редактирования.')}if(b.id==='supportReport')showReport();if(b.id==='copyReport')copy(reportText());});
const materialsBase=materials;materials=function(){materialsBase();const favorites=missions.map((_,i)=>i).filter(i=>state.fields['bookmark_'+i]);document.querySelector('.lesson').insertAdjacentHTML('afterbegin',`<section class="content-block"><h2>Быстрый доступ</h2><div class="actions"><button class="primary" data-view="help">Центр помощи</button><button class="secondary" data-view="preflight">Проверка ролика</button></div><h3>Мои миссии</h3>${favorites.length?favorites.map(i=>`<button class="bookmark-link" data-lesson="${i}">${missions[i][0]} <svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 12h16m-6-6 6 6-6 6"/></svg></button>`).join(''):'<p class="note">Нажми «Сохранить миссию» в уроке, чтобы быстро возвращаться к нему.</p>'}</section>`)};
render(KadrState.route(location.hash),'replace');
